```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulator</title>
    <style>
        #pendulumCanvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="pendulumCanvas" width="400" height="400"></canvas>
    <input id="initialAngle" type="number" value="45" />
    <input type="button" id="startButton" value="Release" />

    <script>
        let canvas = document.getElementById('pendulumCanvas');
        let ctx = canvas.getContext('2d');
        let pendulumLength = 200;
        let initialAngle = 45;
        let gravity = 9.81;
        let thickness = 10;
        let release = false;
        let angle = initialAngle * Math.PI / 180;
        let velocity = 0;
        let angularVelocity = 0;

        function animate() {
            if (release) {
                angle += angularVelocity;
                velocity += -gravity * Math.sin(angle) / pendulumLength;
                angularVelocity += -gravity * Math.cos(angle) / pendulumLength;

                if (Math.abs(velocity) < 0.01) {
                    release = false;
                }
            }

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.moveTo(canvas.width/2, canvas.height/2);
            ctx.lineTo(canvas.width/2 + pendulumLength * Math.sin(angle), canvas.height/2 - pendulumLength * Math.cos(angle));
            ctx.lineWidth = thickness;
            ctx.stroke();

            requestAnimationFrame(animate);
        }

        document.getElementById('startButton').addEventListener('click', function() {
            release = true;
        });

        document.getElementById('initialAngle').addEventListener('input', function() {
            initialAngle = parseInt(document.getElementById('initialAngle').value);
            angle = initialAngle * Math.PI / 180;
        });

        animate();
    </script>
</body>
</html>
```

